INSERT INTO email_settings (link_id, signature_on_replies_forwards, signature, read_receipts_enabled) VALUES ($1, COALESCE($2, FALSE), $3, COALESCE($4, TRUE)) ON CONFLICT (link_id) DO UPDATE SET signature_on_replies_forwards = COALESCE($2, email_settings.signature_on_replies_forwards), signature = COALESCE($3, email_settings.signature), read_receipts_enabled = COALESCE($4, email_settings.read_receipts_enabled), updated_at = NOW() RETURNING link_id, signature_on_replies_forwards, signature, read_receipts_enabled
